files.router.js:
const routes = {
  'GET /': () => ({ body: 'home' }),
  'POST /echo': (payload) => ({ body: payload }),
};

function dispatch(method, path, payload) {
  const handler = routes[method + ' ' + path];
  if (!handler) { throw new Error('no route: ' + method + ' ' + path); }
  return handler(payload);
}

module.exports = { dispatch };

