files.config-loader.js:
const fs = require('fs');

function loadConfig(path, callback) {
  fs.readFile(path, 'utf8', (err, data) => {
    if (err) { callback(err); return; }
    try {
      callback(null, JSON.parse(data));
    } catch (e) {
      callback(e);
    }
  });
}

module.exports = { loadConfig };

