files.utils.js:
function slugify(title) {
  const trimmed = title.trim().toLowerCase();
  let out = '';
  for (const ch of trimmed) {
    if (ch === ' ') {
      out += '-';
    } else if (/[a-z0-9]/.test(ch)) {
      out += ch;
    } else {
      out += '';
    }
  }
  return out;
}

function shout(title) {
  return slugify(title).toUpperCase().replace(/-/g, '_');
}

module.exports = { slugify, shout };

